6: const useCreateUser = () => {
7:   const [isLoading, setIsLoading] = useState(false);
8:   const [data, setData] = useState(undefined);
9:   const [error, setError] = useState(undefined);
10:   const navigate = useNavigate();
11: 
12:   const createUser = async (nome, email, senha, tipoUsuarioId) => {
13:     setIsLoading(true);
14:     usersMethods
15:       .createUsuario({
16:         nome,
17:         email,
18:         senha,
19:         tipoUsuarioId,
20:       })
21:       .then((resp) => {
22:         setData(resp);
23:         setError(undefined);
24:         setIsLoading(false);
25:         if (tipoUsuarioId === tipoUsuario.CLIENTE) {
26:           navigate(routes.LOGIN);
27:         } else {
28:           navigate(routes.HOME);
29:         }
30:       })
31:       .catch((err) => {
32:         setIsLoading(false);
33:         setError(err);
34:         console.error("Erro ao criar usuário.", err);
35:       });
36:   };
37: 
38:   return { createUser, data, isLoading, error };
39: };
40: 
41: export default useCreateUser;

